import { test, expect } from '@playwright/test';

test.describe('Data Tables Responsive Behavior', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should stack table vertically on mobile viewport', async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });

    // Wait for table to be visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get all table rows
    const rows = page.getByRole('row');
    const rowCount = await rows.count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify table has display: block or similar stacking behavior on mobile
    const tableElement = await page.locator('table').first();
    const computedStyle = await tableElement.evaluate((el) => {
      return window.getComputedStyle(el).display;
    });

    // On mobile, table should be block or grid for stacking
    expect(['block', 'grid', 'flex']).toContain(computedStyle);

    // Verify table cells are stacked vertically
    const firstRow = rows.first();
    const cells = firstRow.getByRole('cell');
    const cellCount = await cells.count();

    if (cellCount > 0) {
      const firstCell = cells.first();
      const secondCell = cells.nth(1);

      const firstCellBox = await firstCell.boundingBox();
      const secondCellBox = await secondCell.boundingBox();

      // On mobile, cells should be stacked vertically (different top positions)
      if (firstCellBox && secondCellBox) {
        expect(secondCellBox.y).toBeGreaterThan(firstCellBox.y);
      }
    }
  });

  test('should display table normally on tablet viewport', async ({ page }) => {
    // Set tablet viewport
    await page.setViewportSize({ width: 768, height: 1024 });

    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get table header cells
    const headerCells = page.getByRole('columnheader');
    const headerCount = await headerCells.count();
    expect(headerCount).toBeGreaterThan(0);

    // Verify headers are visible and arranged horizontally
    if (headerCount >= 2) {
      const firstHeader = headerCells.first();
      const secondHeader = headerCells.nth(1);

      const firstHeaderBox = await firstHeader.boundingBox();
      const secondHeaderBox = await secondHeader.boundingBox();

      // On tablet, headers should be arranged horizontally
      if (firstHeaderBox && secondHeaderBox) {
        expect(secondHeaderBox.x).toBeGreaterThan(firstHeaderBox.x);
      }
    }
  });

  test('should display table in full width on desktop viewport', async ({ page }) => {
    // Set desktop viewport
    await page.setViewportSize({ width: 1920, height: 1080 });

    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get table dimensions
    const tableBox = await table.boundingBox();
    expect(tableBox).not.toBeNull();

    if (tableBox) {
      // Table should take significant width on desktop
      expect(tableBox.width).toBeGreaterThan(800);
    }

    // Verify all columns are visible
    const headerCells = page.getByRole('columnheader');
    const headerCount = await headerCells.count();
    expect(headerCount).toBeGreaterThan(0);

    // All headers should be visible without horizontal scrolling
    for (let i = 0; i < headerCount; i++) {
      const header = headerCells.nth(i);
      await expect(header).toBeInViewport();
    }
  });

  test('should maintain data integrity when stacking on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get all rows
    const rows = page.getByRole('row');
    const rowCount = await rows.count();

    // Verify each row has consistent number of cells
    const cellCountsPerRow: number[] = [];

    for (let i = 0; i < Math.min(rowCount, 3); i++) {
      const row = rows.nth(i);
      const cells = row.getByRole('cell');
      const cellCount = await cells.count();
      cellCountsPerRow.push(cellCount);
    }

    // All rows should have same number of cells
    if (cellCountsPerRow.length > 1) {
      const firstRowCellCount = cellCountsPerRow[0];
      cellCountsPerRow.forEach((count) => {
        expect(count).toBe(firstRowCellCount);
      });
    }
  });

  test('should handle table with data attributes for mobile labels', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get first data row
    const rows = page.getByRole('row');
    const firstDataRow = rows.nth(1); // Skip header row

    // Verify cells have data attributes or aria-labels for mobile display
    const cells = firstDataRow.getByRole('cell');
    const cellCount = await cells.count();

    if (cellCount > 0) {
      const firstCell = cells.first();

      // Check for data-label attribute or aria-label
      const hasDataLabel = await firstCell.evaluate((el) => {
        return el.hasAttribute('data-label') || el.hasAttribute('aria-label');
      });

      // Cell should have some way to identify its column on mobile
      expect(
        hasDataLabel || 
        (await firstCell.textContent()).length > 0
      ).toBeTruthy();
    }
  });

  test('should scroll horizontally on mobile if table exceeds viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Check if table container allows horizontal scroll
    const tableContainer = page.locator('[role="table"]').first();
    const isScrollable = await tableContainer.evaluate((el) => {
      return el.scrollWidth > el.clientWidth;
    });

    if (isScrollable) {
      // Verify horizontal scrollbar is accessible
      const scrollWidth = await tableContainer.evaluate((el) => el.scrollWidth);
      const clientWidth = await tableContainer.evaluate((el) => el.clientWidth);

      expect(scrollWidth).toBeGreaterThan(clientWidth);
    }
  });
});
